				if e != nil || rcMap(rcMap(out["serving_proof"])["replication"])["peer_applied_sequence"] != 3 {
					t.Fatal(out, e)
				}
			} else if e == nil {
				t.Fatalf("accepted %s", name)
			}
		})
	}
}

