func (a api) request(ctx context.Context, method, url, token string, input, output any) error {
	var body io.Reader
	if input != nil {
		wire, err := json.Marshal(input)
		if err != nil {
			return err
		}
		body = bytes.NewReader(wire)
	}
	req, err := http.NewRequestWithContext(ctx, method, url, body)
	if err != nil {
		return err
	}
	if token != "" {
		req.Header.Set("Authorization", "Bearer "+token)
	}
	req.Header.Set("Content-Type", "application/json")
	req.Header.Set("Cache-Control", "no-cache")
	response, err := a.client.Do(req)
	if err != nil {
		return errors.New("deployment guard HTTP request did not complete")
	}
	defer response.Body.Close()
	if response.StatusCode < 200 || response.StatusCode >= 300 {
		return fmt.Errorf("deployment guard HTTP status %d", response.StatusCode)
	}
	if output == nil {
		return nil
	}
	wire, err := io.ReadAll(io.LimitReader(response.Body, 4<<20))
	if err != nil {
		return err
	}
	return json.Unmarshal(wire, output)
}

// Main ancestry, rather than workflow outcome, survives a failed deployment.
// Bound API work; an exhausted history fails visibly instead of assuming green.
func (a api) history(ctx context.Context, service string) ([]commit, error) {
	var commits []commit
	if err := a.request(ctx, "GET", forge+service+"/commits?sha=main&per_page=50", a.readToken, nil, &commits); err != nil {
		return nil, err
	}
	found := false
	for i := range commits {
		for page := 1; ; page++ {
			var statuses []struct {
				Context   string    `json:"context"`
				State     string    `json:"state"`
				CreatedAt time.Time `json:"created_at"`
			}
			url := fmt.Sprintf("%s%s/commits/%s/statuses?per_page=50&page=%d", forge, service, commits[i].SHA, page)
			if err := a.request(ctx, "GET", url, a.readToken, nil, &statuses); err != nil {
				return nil, err
			}
			for _, status := range statuses {
				if status.Context == qualifiedContext && status.State == "success" &&
					!status.CreatedAt.IsZero() && (commits[i].GreenAt.IsZero() || status.CreatedAt.Before(commits[i].GreenAt)) {
					commits[i].GreenAt = status.CreatedAt
					found = true
				}
			}
			if len(statuses) < 50 {
				break
			}
		}
	}
	if !found {
		return nil, errors.New("no qualified-main marker in the latest 50 commits; verify pipeline markers")
	}
	return commits, nil
}

// Do not reset the clock when another green build overtakes a pending build.
func pending(history []commit, version string, now time.Time) (commit, time.Duration, error) {
	var newest commit
	var oldest time.Time
	found := false
	for _, entry := range history {
		if entry.SHA == version {
			found = true
			break
		}
		if entry.GreenAt.IsZero() {
			continue
		}
		if entry.GreenAt.After(now.Add(30 * time.Second)) {
			return commit{}, 0, errors.New("qualified-main timestamp is ahead of the clock")
		}
		if newest.SHA == "" {
			newest = entry
		}
		if oldest.IsZero() || entry.GreenAt.Before(oldest) {
			oldest = entry.GreenAt
		}
	}
	if !found {
		return commit{}, 0, errors.New("incomplete qualified-main history: deployed revision is outside the checked ancestry")
	}
	if oldest.IsZero() {
		return newest, 0, nil
	}
	return newest, now.Sub(oldest), nil

func proofError(proof observation, now time.Time) error {
	if proof.Status != http.StatusOK || !release.ValidSourceRevision(proof.Version) {
		return errors.New("live deployment proof is missing or invalid")
	}
	if age := now.Sub(proof.ObservedAt); age < -30*time.Second || age > releasechannel.MaxPinAge {
		return errors.New("live deployment proof timestamp is stale or ahead of the clock")
	}
	return nil
}

func (a api) alert(ctx context.Context, findings []string) error {
	base := forge + "ts-orchestrator/issues"
	slices.Sort(findings)
	body := "@mariogk Automatic deployment guard: a qualified main build has not reached every region within 30 minutes, or its live proof is unavailable.\n\n"
	body += strings.Join(findings, "\n") + "\n\nPart of TS-768. See docs/deploy-pipeline.md and the scheduled deploy-lag.yml run."
	for page := 1; ; page++ {
		var issues []struct {
			Number      int       `json:"number"`
			Title       string    `json:"title"`
			Body        string    `json:"body"`
			PullRequest *struct{} `json:"pull_request"`
		}
		if err := a.request(ctx, "GET", fmt.Sprintf("%s?state=open&per_page=50&page=%d", base, page),
			a.writeToken, nil, &issues); err != nil {
			return err
		}
		for _, issue := range issues {
			if issue.PullRequest != nil || issue.Title != alertTitle {
				continue
			}
			if len(findings) == 0 {
				return a.request(ctx, "PATCH", fmt.Sprintf("%s/%d", base, issue.Number), a.writeToken, map[string]string{"state": "closed"}, nil)
			}
			if issue.Body == body {
				return nil
			}
			return a.request(ctx, "PATCH", fmt.Sprintf("%s/%d", base, issue.Number), a.writeToken, map[string]string{"body": body}, nil)
		}
		if len(issues) == 0 {
			break
		}
	}
	if len(findings) == 0 {
		return nil
	}
	return a.request(ctx, "POST", base, a.writeToken, map[string]any{
		"title": alertTitle, "body": body, "assignees": []string{"mariogk"},
	}, nil)
}

func run(ctx context.Context, a api, now func() time.Time,
	readNative func(context.Context, string, string) (observation, error), notify bool) error {
	collectCtx, cancelCollection := context.WithTimeout(ctx, collectionBudget)
	defer cancelCollection()
	regions, discoveryErr := atlas.DiscoverServingCells(collectCtx, a.client)
	histories := make(map[string][]commit)
	var findings []string
	if discoveryErr != nil {
		findings = append(findings, "- Serving-region discovery unavailable: "+discoveryErr.Error())
	}
	var lock sync.Mutex
	var workers sync.WaitGroup
	for _, service := range services {
		workers.Go(func() {
			history, err := a.history(collectCtx, service)
			lock.Lock()
			defer lock.Unlock()
			if err != nil {
				findings = append(findings, "- "+service+": qualified-main history unavailable")
				return
			}
			histories[service] = history
		})
	}
	workers.Wait()
	var observed []observation
	for _, service := range services[:3] {
		for _, region := range regions {
			workers.Go(func() {
				proof, err := readNative(collectCtx, service, region)
				lock.Lock()
				defer lock.Unlock()
				if err != nil {
					findings = append(findings, "- "+service+" "+region+": live fleet proof unavailable")
					return
				}
				observed = append(observed, proof)
			})
		}
	}
	var edge []observation
	err := a.request(collectCtx, "GET", "https://status.terrascale.tech/api/v1/deployments", "", nil, &edge)
	workers.Wait()
	cancelCollection()
	if err != nil {
		findings = append(findings, "- Edge deployment observations unavailable from ts-status")
	}
	// Require every discovered region, including its Status vantage build.
	for _, service := range services[3:] {
		for _, region := range regions {
			targets := []string{"service"}
			if service == "ts-status" {
				targets = append(targets, "vantage")
			}
			for _, target := range targets {
				proof := observation{Service: service, Region: region, Target: target}
				for _, row := range edge {
					if row.Service == service && row.Region == region && row.Target == target {
						proof = row
						break
					}
				}
				observed = append(observed, proof)
			}
		}
	}
	for _, proof := range observed {
		checkedAt := now()
		if err := proofError(proof, checkedAt); err != nil {
			findings = append(findings, "- "+proof.Service+" "+proof.Region+" "+proof.Target+": "+err.Error())
			continue
		}
		history, ok := histories[proof.Service]
		if !ok {
			continue
		}
		target, lag, err := pending(history, proof.Version, checkedAt)
		if err != nil {
			findings = append(findings, "- "+proof.Service+" "+proof.Region+": "+err.Error())
			continue
		}
		fmt.Printf("%s %s %s deployed=%s target=%s oldest-pending=%s\n",
			proof.Service, proof.Region, proof.Target, proof.Version, target.SHA, lag.Round(time.Second))
		if lag >= lagLimit {
			findings = append(findings, fmt.Sprintf("- %s %s %s: target `%s`; deployed `%s`; qualified build overdue.",
				proof.Service, proof.Region, proof.Target, target.SHA, proof.Version))
		}
	}
	if notify {
		// Collection failure still gets a bounded opportunity to deliver its alert.
		alertCtx, cancelAlert := context.WithTimeout(context.WithoutCancel(ctx), notificationBudget)
		defer cancelAlert()
		if err := a.alert(alertCtx, findings); err != nil {
			return fmt.Errorf("deployment alert could not be delivered: %w", err)
		}
	}
	if len(findings) > 0 {
		return fmt.Errorf("deployment guard found %d lag/proof failures", len(findings))
	}
	return nil
}

const (
	DiscoveryURL      = "https://atlas.terrascale.tech"
	discoveryTimeout  = 10 * time.Second
	maxDiscoveryBytes = 256 << 10
)

// Discovery is Atlas' GET /v1/discovery answer (ts-atlas
// docs/discovery-v1.md): the published regions ranked for the caller.
type Discovery struct {
	V       int    `json:"v"`
	Updated int64  `json:"updated"`
	Stale   bool   `json:"stale"`
	Closest string `json:"closest"`
	// Regions carry their last health: ok, unknown or down.
	Regions  []DiscoveredRegion `json:"regions"`
	Services []Service          `json:"services"`
}

// ServingCells is the orch-published, signed-spec topology's membership.
// Routing health does not remove an admitted cell from deployment.
func (d Discovery) ServingCells(now time.Time) ([]string, error) {
	if d.V != 1 || len(d.Regions) == 0 || len(d.Regions) > catalog.MaxRegions || d.Stale || d.Updated <= 0 ||
		now.Sub(time.Unix(d.Updated, 0)) > StaleAfter || time.Unix(d.Updated, 0).Sub(now) > Interval {
		return nil, errors.New("serving-region discovery is empty, stale or invalid")
	}
	cells := make([]string, 0, len(d.Regions))
	for _, region := range d.Regions {
		name, _, _ := strings.Cut(region.ID, "-")
		entry, known := catalog.LookupName(name)
		if !known {
			return nil, fmt.Errorf("serving-region discovery includes unsupported cell %q", region.ID)
		}
		id, err := naming.RegionCell(entry.Cell).Name()
		if err != nil || id != region.ID || slices.Contains(cells, entry.Cell) {
			return nil, fmt.Errorf("serving-region discovery includes duplicate or unsupported cell %q", region.ID)
		}
		cells = append(cells, entry.Cell)
	}
	slices.Sort(cells)
	return cells, nil
}

// DiscoverServingCells reads membership from ts-orch's published Atlas topology.
func DiscoverServingCells(ctx context.Context, client *http.Client) ([]string, error) {
	discovery, err := Discover(ctx, client, DiscoveryURL)
	if err != nil {
		return nil, err
	}
	return discovery.ServingCells(time.Now().UTC())
}

func Discover(ctx context.Context, client *http.Client, baseURL string) (Discovery, error) {
	if !httpsURL(baseURL) {
		return Discovery{}, errors.New("atlas url must be https")
	}
	ctx, cancel := context.WithTimeout(ctx, discoveryTimeout)
	defer cancel()
	request, err := http.NewRequestWithContext(ctx, http.MethodGet, strings.TrimSuffix(baseURL, "/")+"/v1/discovery", nil)
	if err != nil {
		return Discovery{}, err
	}
	noRedirect := *client
	noRedirect.CheckRedirect = func(*http.Request, []*http.Request) error { return http.ErrUseLastResponse }
	response, err := noRedirect.Do(request)
	if err != nil {
		return Discovery{}, fmt.Errorf("atlas discovery: %w", err)
	}
	defer response.Body.Close()
	body, err := io.ReadAll(io.LimitReader(response.Body, maxDiscoveryBytes+1))
	if err != nil {
		return Discovery{}, fmt.Errorf("atlas discovery: %w", err)
	}
	if response.StatusCode != http.StatusOK {
		return Discovery{}, fmt.Errorf("atlas discovery answered %s", response.Status)
	}
	if len(body) > maxDiscoveryBytes {
		return Discovery{}, fmt.Errorf("atlas discovery exceeds %d bytes", maxDiscoveryBytes)
	}
	var discovery Discovery
	if err := json.Unmarshal(body, &discovery); err != nil {
		return Discovery{}, fmt.Errorf("decode atlas discovery: %w", err)
	}
	if discovery.V != 1 {
		return Discovery{}, fmt.Errorf("atlas discovery version %d is not 1", discovery.V)
	}
	return discovery, nil
}

// Interval is how often the leader publishes: the contract asks for
// about 10 s, well inside Atlas' STALE_AFTER_S (60 s).
Interval = 10 * time.Second
// StaleAfter is Atlas' STALE_AFTER_S: past it every region reads
// "unknown", so the loop alerts once no publish succeeded for this long.
StaleAfter = 60 * time.Second

func httpsURL(raw string) bool {
	parsed, err := url.Parse(raw)
	return err == nil && parsed.Scheme == "https" && parsed.Host != ""
}

// Server roles.
const (
	Controller = "ctl"
	Member     = "db"
	Gateway    = "gw"
)

// ErrName reports a name outside the scheme.
var ErrName = errors.New("name does not follow ts-<region>-<n>[-data], <region>-<index>[-<role>-<n>[-data]] or <region>-<index>-pool-<pool>-<n>")

var scheme = regexp.MustCompile(`^([a-z]+)-[1-9][0-9]{0,2}(?:-(?:ctl|gw)-[1-9][0-9]{0,2}|-db-[1-9][0-9]{0,2}(?:-data)?|` +
	`-pool-[a-z][a-z0-9]{1,11}-[1-9][0-9]{0,2})?$`)

var nodeScheme = regexp.MustCompile(`^ts-([a-z]+)-[1-9][0-9]{0,2}(?:-data)?$`)

// Cell is one region's cell.
type Cell struct {
	Region string // catalog cell code, e.g. GRU
	Index  int
}

// RegionCell returns the cell a region runs. Every region runs one cell
// today, cell 1.
func RegionCell(region string) Cell { return Cell{Region: region, Index: 1} }

// Name returns the cell name, e.g. gru-1.
func (c Cell) Name() (string, error) {
	return valid(fmt.Sprintf("%s-%d", strings.ToLower(c.Region), c.Index))
}

func Validate(name string) error {
	match := nodeScheme.FindStringSubmatch(name)
	if match == nil {
		match = scheme.FindStringSubmatch(name)
	}
	if match == nil || !catalog.IsCell(strings.ToUpper(match[1])) {
		return fmt.Errorf("%w: %q", ErrName, name)
	}
	return nil

func valid(name string) (string, error) {
	if err := Validate(name); err != nil {
		return "", err
	}
	return name, nil
}

// entries is ordered: placement assigns permanent members in this order.
var entries = [...]Entry{
	{Cell: GRU, OCIRegion: "sa-saopaulo-1", OCIRegionKey: "GRU", City: "São Paulo", Country: "BR", Latitude: -23.43, Longitude: -46.47},
	{Cell: SFO, OCIRegion: "us-sanjose-1", OCIRegionKey: "SJC", City: "San Jose", Country: "US", Latitude: 37.34, Longitude: -121.89},
	{Cell: FRA, OCIRegion: "eu-frankfurt-1", OCIRegionKey: "FRA", City: "Frankfurt", Country: "DE", Latitude: 50.11, Longitude: 8.68},

// MaxRegions bounds the regions in one deployment's roster; it matches the
// roster limit in globalcontrol.
const MaxRegions = 32

// Len is the number of catalog entries.
const Len = len(entries)

// Entries returns a copy of the ordered catalog.
func Entries() []Entry { return append([]Entry(nil), entries[:]...) }

// Founded returns the regions with a reserved address plan
// (docs/network/address-plan.md). ts-orch region create (TS-804) extends it.
func Founded() []Entry { return append([]Entry(nil), entries[:foundedCount]...) }

func LookupName(name string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Name() == name {
			return entry, true
		}
	}
	return Entry{}, false
}

// Lookup returns the entry for an exact upper-case cell code.
func Lookup(cell string) (Entry, bool) {
	for _, entry := range entries {
		if entry.Cell == cell {
			return entry, true
		}
	}
	return Entry{}, false
}

// IsCell reports whether cell is an exact upper-case supported cell code.
func IsCell(cell string) bool {
	_, ok := Lookup(cell)
	return ok
}

// PinRefreshInterval keeps inventories current; MaxPinAge bounds how long
// pruning can use one when collection or publication stops succeeding.
const (
	PinRefreshInterval = 30 * time.Second
	MaxPinAge          = 2 * time.Minute
)

func TestSchedulerGoWrapper(t *testing.T) {
	if os.Getenv("TS_SCHEDULER_WRAPPER") != "1" {
		return
	}
	marker := slices.Index(os.Args, "--")
	if marker < 0 || marker+1 >= len(os.Args) {
		os.Exit(2)
	}
	args := os.Args[marker+1:]
	running := args[0] == "test" && !slices.Contains(args, "-list")
	idle := false
	if i := slices.Index(args, "-run"); i >= 0 && i+1 < len(args) {
		for _, lab := range schedulerLabs {
			idle = idle || args[i+1] == "^("+lab+")$"
		}
	}
	update := func(delta int) {
		f, err := os.OpenFile(os.Getenv("SCHEDULER_STATE"), os.O_RDWR, 0)
		if err != nil {
			panic(err)
		}
		defer f.Close()
		if err := syscall.Flock(int(f.Fd()), syscall.LOCK_EX); err != nil {
			panic(err)
		}
		data, err := os.ReadFile(f.Name())
		if err != nil {
			panic(err)
		}
		var state schedulerState
		if err := json.Unmarshal(data, &state); err != nil {
			panic(err)
		}
		state.Active += delta
		state.Maximum = max(state.Maximum, state.Active)
		if idle {
			state.IdleActive += delta
			state.IdleMaximum = max(state.IdleMaximum, state.IdleActive)
		} else if running {
			state.CPUActive += delta
			state.CPUMaximum = max(state.CPUMaximum, state.CPUActive)
		}
		if delta >= 0 {
			state.Commands = append(state.Commands, args)
			if running {
				state.GORACE = append(state.GORACE, os.Getenv("GORACE"))
			}
		}
		data, err = json.Marshal(state)
		if err != nil {
			panic(err)
		}
		if _, err := f.WriteAt(data, 0); err != nil {
			panic(err)
		}
		if err := f.Truncate(int64(len(data))); err != nil {
			panic(err)
		}
	}
	if running {
		update(1)
	} else {
		update(0)
	}
	if slices.Contains(args, "-list") && os.Getenv("FAIL_LIST") != "" {
		fmt.Println("intentional discovery failure")
		os.Exit(1)
	}
	cmd := exec.Command(os.Getenv("REAL_GO"), args...)
	cmd.Stdin = os.Stdin
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	err := cmd.Run()
	if running {
		update(-1)
	}
	if err != nil {
		if cmd.ProcessState == nil {
			fmt.Fprintln(os.Stderr, err)
			os.Exit(1)
		}
		os.Exit(cmd.ProcessState.ExitCode())
	}
	os.Exit(0)
}

