	f.env = map[string]string{"GO": wrapper, "REAL_GO": realGo, "SCHEDULER_TEST_BINARY": executable, "TS_SCHEDULER_WRAPPER": "1", "GOFLAGS": "-p=2", "GOMAXPROCS": "2", "GORACE": "halt_on_error=1",
